-- 참가자를 선수 목록에 등록 (이미 있거나, 다른 선수의 부캐로 통합된 닉네임은 건너뜀)
insert into public.members (nickname)
select v.nickname from (values
  ('4드론전진8배럭'),
  ('DoYouKnowIMO'),
  ('Eddie'),
  ('youuuuu'),
  ('다이아행역행열차'),
  ('대전보문산메아리'),
  ('두유댕댕이'),
  ('따뜻하게말한마디'),
  ('라스트볼'),
  ('만촌인터불고'),
  ('메이타'),
  ('뽀스탈게요'),
  ('뽕뽕태'),
  ('뿅뿅태'),
  ('송지이즈선생님'),
  ('얘들아 그거 맞냐'),
  ('오늘만사는남자'),
  ('우효원'),
  ('윤호형'),
  ('이민재'),
  ('잠실아펠가모'),
  ('전기수')
) as v(nickname)
where not exists (
  select 1 from public.members m
  where m.nickname = v.nickname or coalesce(m.aliases, '[]'::jsonb) ? v.nickname
)
on conflict (nickname) do nothing;

commit;

